const paths={bowl:'M3 10h18c0 12-18 12-18 0ZM7 6q-2-2 0-4m5 4q-2-2 0-4m5 4q-2-2 0-4',home:'m3 10 9-7 9 7v11H3Zm6 11v-8h6v8',map:'m3 4 6-2 6 3 6-2v17l-6 2-6-3-6 2ZM9 2v17m6-14v17',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',shop:'M3 10v11h18V10M2 10l2-7h16l2 7M2 10q2 4 5 0 2 4 5 0 2 4 5 0 3 4 5 0M8 21v-7h8v7',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Zm-2 5 6 6',pin:'M19 9c0 6-7 12-7 12S5 15 5 9a7 7 0 0 1 14 0ZM14 9a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',heart:'M12 21 3 12C-3 5 6-1 12 5 18-1 27 5 21 12Z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 6v6l4 2',coffee:'M3 7h13v8a6 6 0 0 1-12 0V7Zm13 1h3a3 3 0 1 1 0 6h-3M3 21h15M7 3v1m5-1v1',leaf:'M20 3C6 2 1 11 6 17 12 23 23 16 20 3ZM4 21l12-12',noodle:'M4 12h16c0 11-16 11-16 0ZM8 9V2m4 7V2m4 7V2m-8 2h8',drink:'M6 6h12l-2 16H8ZM11 17l3-15h5M6 6h12',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',cake:'M3 10h18v11H3ZM2 10q3-5 6 0 4-5 8 0 3-5 6 0M6 6h12M8 6V3m4 3V2m4 4V3',cart:'M2 3h3l3 13h11l3-9H6M10 21a1 1 0 1 1 0-2 1 1 0 0 1 0 2Zm8 0a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z',message:'M21 3H3v14h5l4 4 4-4h5ZM7 8h10M7 12h6',camera:'M3 6h5l2-3h4l2 3h5v15H3ZM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',order:'M5 3h14v18l-3-2-4 2-4-2-3 2ZM8 7h8M8 11h8M8 15h4',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3ZM20 2v4m-2-2h4',wheel:'M21 12a9 9 0 1 1-9-9m0 0v5m7-5v5h-5M12 8v4l3 3',close:'m6 6 12 12M6 18 18 6',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',plus:'M12 4v16M4 12h16',check:'m5 12 4 4L20 5',chart:'M3 3v18h18M7 17v-6m5 6V7m5 10V3',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',truck:'M2 5h12v12H2Zm12 4h4l4 4v4h-8M7 19a2 2 0 1 1-4 0 2 2 0 0 1 4 0Zm13 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',share:'M17 4a2 2 0 1 1 0 4 2 2 0 0 1 0-4ZM5 10a2 2 0 1 1 0 4 2 2 0 0 1 0-4Zm12 6a2 2 0 1 1 0 4 2 2 0 0 1 0-4ZM7 11l8-4M7 13l8 4'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.bowl}"/></svg>`;
const cats=[['食堂美食','bowl','#f9ebd6','#cda66e'],['面食粉面','noodle','#f8e5de','#cb9b7e'],['轻食','leaf','#eaf0dc','#9aaf75'],['咖啡','coffee','#ede5dc','#b89e80'],['奶茶饮品','drink','#e5eee6','#9aac7d'],['早餐','sun','#f7efda','#cfb273'],['甜品小吃','cake','#f5e7eb','#c5a0ac'],['超市','cart','#e8edf5','#9baac2']];
const venues=[{id:1,name:'梧桐苑',kind:'食堂',x:375,y:246,floors:[1,2,3],description:'校方资料称梧桐苑位于宿舍区、图书馆和教学楼之间；内部档口为示例。',crowdCapacity:65},{id:2,name:'稻香苑',kind:'食堂',x:605,y:352,floors:[1],description:'校方资料称位于成都校区招待所旁；2025年资料注明暂停营业，当前状态未核实。此处提供模拟菜单。',crowdCapacity:35},{id:4,name:'校园咖啡点',kind:'咖啡',x:385,y:104,floors:[1],description:'模拟校园咖啡门店，用于展示分类与点位导航。',crowdCapacity:15},{id:5,name:'生活区超市',kind:'超市',x:142,y:354,floors:[1],description:'模拟生活区超市，用于展示校园便利商品。',crowdCapacity:15}];
let session=null;try{session=JSON.parse(sessionStorage.getItem('xiaowei-session'));}catch(e){};
let page=session?.role==='merchant'?'dashboard':'home',loginRole='student',category='全部',query='',sort='推荐',mapLevel='campus',venueId=1,floor=1,stallId=1,mapKind='全部',myOnly=false,reviewScore=5,photo='',wheelType='菜品',wheelAngle=0,spinning=false;
const activeShop=()=>model.shop(session?.shopId||1),venue=id=>venues.find(v=>v.id===Number(id)),place=s=>`${venue(s.venueId)?.name||s.place.split(' · ')[0]} · ${s.floor||1}F · ${s.stall||'01'}${s.venueId<=2?'档口':'门店'}`;
const brand=()=>`<span class="brand-logo">${icon('bowl')}</span><span><span class="brand-name">校味</span><small>CAMPUS FLAVORS</small></span>`;
const studentNav=[['home','home','首页'],['map','map','美食地图'],['feed','camera','打卡动态'],['mine','user','我的']];
const merchantNav=[['dashboard','chart','营业概览'],['manage','bowl','菜品管理'],['merchantOrders','order','订单处理'],['merchantReviews','message','点评与留言'],['settings','settings','门店设置']];
function footer(){return `<footer class="footer">校味 · 校园美食点评与推荐<br>四川农业大学成都校区场景范例 · 菜品、内部位置、人流及履约均为模拟数据</footer>`;}
function render(){if(!session){$('#app').innerHTML=loginView();window.crousCloud?.update();return;}const merchant=session.role==='merchant';$('#app').innerHTML=`<header class="header"><button class="brand" onclick="ui.go('${merchant?'dashboard':'home'}')">${brand()}</button>${!merchant?`<nav class="main-nav">${studentNav.map(([id,ic,t])=>`<button class="${page===id?'active':''}" onclick="ui.go('${id}')">${t}</button>`).join('')}</nav>`:`<span class="text-muted">商家工作台 · ${esc(activeShop().name)}</span>`}<div class="header-spacer"></div><button class="campus-button" onclick="ui.campus()">${icon('pin')}川农 · 成都校区</button><button id="cloud-status" class="sync-status" onclick="ui.syncInfo()">本机体验</button><button class="account" onclick="${merchant?'ui.logout()':"ui.go('mine')"}"><span class="avatar">${esc((session.name||'同学').slice(0,1))}</span><span class="account-name">${esc(session.name)}${merchant?' · 退出':''}</span></button></header>${merchant?`<div class="merchant-shell"><aside class="merchant-sidebar"><small>我的经营窗口</small>${merchantNav.map(([id,ic,t])=>`<button class="${page===id?'active':''}" onclick="ui.go('${id}')">${icon(ic)}${t}</button>`).join('')}</aside><main class="merchant-content">${views[page]?.()||views.dashboard()}${footer()}</main></div>`:`<main class="content">${views[page]?.()||views.home()}${footer()}</main><nav class="mobile-nav">${studentNav.map(([id,ic,t])=>`<button class="${page===id?'active':''}" onclick="ui.go('${id}')">${icon(ic)}${t}</button>`).join('')}</nav>`}`;window.crousCloud?.update();}
function loginView(){return `<div class="login-shell"><section class="login-story"><div class="brand">${brand()}</div><h1>校园里的好味道，<br>找到<em>你想吃的那一口。</em></h1><p>逛食堂、看点评、记下喜欢的味道。<br>从熟悉的那一顿，到下一家值得试试的档口。</p><div class="login-illustration">${foodArt(model.dish(3))}<div class="float-note">鸡胸蔬菜能量碗<br><strong>★ 4.9 · 清淡又满足</strong></div></div><p>四川农业大学 · 成都校区场景范例</p></section><section class="login-main"><form class="login-box" onsubmit="ui.login(event)"><div class="brand">${brand()}</div><h2>欢迎来到校味</h2><p>选择你的身份，开始校园美食体验。</p><div class="role-cards"><button type="button" class="role-card ${loginRole==='student'?'active':''}" onclick="ui.loginRole('student')"><span class="role-check"></span>${icon('user')}<strong>我是学生</strong><small>发现美食 · 点评打卡<br>看看今天吃什么</small></button><button type="button" class="role-card ${loginRole==='merchant'?'active':''}" onclick="ui.loginRole('merchant')"><span class="role-check"></span>${icon('shop')}<strong>我是商家</strong><small>管理菜单 · 发布新品<br>接单与回应反馈</small></button></div><div class="field"><label for="login-name">${loginRole==='student'?'体验昵称':'商家称呼'}</label><input class="input" id="login-name" name="name" value="${esc(loginRole==='student'?model.state.profile.nickname:'商家体验账号')}" maxlength="20" required></div>${loginRole==='merchant'?`<div class="field"><label for="login-shop">选择经营档口（模拟）</label><select class="input" name="shopId" id="login-shop">${model.state.shops.map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(place(s))}</option>`).join('')}</select></div>`:''}<button class="btn primary full" style="margin-top:12px">${loginRole==='student'?'进入校园美食':'进入商家工作台'} ${icon('arrow')}</button><div class="login-note">身份选择用于产品体验，无需填写账号密码。云端记录属于当前登录的平台账号；不会产生真实点餐、支付或配送。</div><button class="help-link" type="button" onclick="ui.about()">了解产品与数据来源</button></form></section></div>`;}
function head(title,sub,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function empty(title,sub){return `<div class="empty">${icon('bowl')}<strong style="display:block">${title}</strong><p>${sub}</p></div>`;}
function card(d){const s=model.shop(d.shopId),saved=model.state.favorites.includes(d.id);return `<article class="dish-card"><div class="food-image" onclick="ui.detail(${d.id})">${foodArt(d)}<span class="image-label">${d.isNew?'本周上新':esc(d.category)}</span><button class="favorite ${saved?'on':''}" aria-label="${saved?'取消收藏':'收藏'}${esc(d.name)}" onclick="event.stopPropagation();ui.favorite(${d.id})">${icon('heart')}</button></div><div class="dish-body"><div class="dish-title"><button onclick="ui.detail(${d.id})">${esc(d.name)}</button><span class="price"><small>¥</small>${d.price}</span></div><div class="place">${icon('pin')}${esc(place(s))}</div><div class="rating-row"><span class="star">★ ${d.count?d.rating.toFixed(1):'待评分'}</span><span>${d.count}条点评</span><span class="wait ${s.minutes>5?'busy':''}">${s.open?'约'+s.minutes+'分钟':'休息中'}</span></div><div class="tags">${d.tags.slice(0,3).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="quote">“${esc(d.quote)}”</div><div class="card-bottom"><span>${esc(s.name)}</span><button onclick="ui.checkin(${d.id})">${icon('camera')}去打卡</button></div></div></article>`;}
function listing(){let ds=model.state.dishes.filter(d=>d.available&&model.shop(d.shopId).open);if(category!=='全部')ds=ds.filter(d=>d.category===category);if(query)ds=ds.filter(d=>(d.name+model.shop(d.shopId).name+place(model.shop(d.shopId))+d.tags.join('')).includes(query));if(sort==='新菜')ds=ds.filter(d=>d.isNew);if(sort==='人少')ds=ds.filter(d=>model.shop(d.shopId).minutes<=5);if(sort==='收藏')ds=ds.filter(d=>model.state.favorites.includes(d.id));ds.sort(sort==='评分高'?(a,b)=>b.rating-a.rating||b.count-a.count:(a,b)=>model.score(b)-model.score(a));return ds.map(card).join('')||empty('没有找到匹配的美食','试试其他分类、关键词或筛选条件。');}
function venueTraffic(v){const ss=model.state.shops.filter(s=>s.venueId===v.id&&s.open),people=ss.reduce((a,s)=>a+s.queue,0);return {people,minutes:ss.length?Math.round(ss.reduce((a,s)=>a+s.minutes,0)/ss.length):0,ratio:Math.min(95,Math.round(people/v.crowdCapacity*100)),label:people<12?'较空闲':people<28?'适中':'较拥挤'};}
function trafficPanel(){return `<section class="side-panel"><h3>${icon('clock')}现在去哪吃</h3><p class="panel-sub">看看食堂人流与档口排队，少等一会儿。</p>${venues.filter(v=>v.kind==='食堂').map(v=>{const t=venueTraffic(v);return `<button class="queue-line" onclick="ui.venue(${v.id})"><span class="queue-mini">${icon('shop')}</span><span><strong>${v.name}</strong><small>${t.people}人排队 · 预计${t.minutes}分钟</small></span><span>${t.label}</span></button><div class="density"><span style="width:${t.ratio}%"></span></div>`;}).join('')}<p class="text-muted">商家维护的模拟人流与等待时间</p><button class="link" onclick="ui.go('map')">查看校园美食地图 ›</button></section>`;}
function homeView(){return `${head('发现校园里的好味道','看同学点评，找食堂新菜，记下你的校园美食。','<span class="small-label">四川农业大学 · 成都校区</span>')}<form class="search-row" onsubmit="ui.searchSubmit(event)"><div class="search-box">${icon('search')}<input id="home-search" name="query" placeholder="搜索菜品、档口或食堂" aria-label="搜索菜品、档口或食堂" value="${esc(query)}" oninput="ui.search(this.value)"><button>搜索</button></div><button type="button" class="assistant-entry" onclick="ui.assistant()">${icon('spark')}<span><strong>今天吃什么</strong><small>用餐助手，帮你挑一顿</small></span></button></form><section class="categories">${cats.map(([name,ic,bg,fg])=>`<button class="category ${category===name?'active':''}" onclick="ui.category('${name}')"><span class="category-visual" style="--catbg:${bg};--catcolor:${fg}">${icon(ic)}</span>${name}</button>`).join('')}</section><section class="hero-strip"><div class="hero-strip-copy"><h2>熟悉的校园，总有新味道。</h2><p>从一份家常盖饭，到课间的一杯咖啡。</p><button class="link" style="margin-top:11px;padding:0" onclick="ui.filter('新菜')">看看本周上新 ${icon('arrow')}</button></div><span class="hero-strip-tag">发现你的下一顿</span><div class="hero-strip-art">${foodArt(model.dish(1))}</div></section><div class="two-col"><section><div class="section-head"><h2>${category==='全部'?'校园美食推荐':category}</h2><small id="result-count">口味不同，喜欢的也可以不同</small></div><div class="filters"><button class="chip ${category==='全部'?'active':''}" onclick="ui.category('全部')">全部分类</button>${['推荐','新菜','评分高','人少','收藏'].map(f=>`<button class="chip ${sort===f?'active':''}" onclick="ui.filter('${f}')">${f}</button>`).join('')}</div><div class="cards" id="food-list">${listing()}</div></section><aside class="aside">${trafficPanel()}<section class="side-panel"><h3>${icon('spark')}用餐小工具</h3><div class="aside-tools"><button class="tool-tile" onclick="ui.assistant()">${icon('spark')}用餐推荐</button><button class="tool-tile" onclick="ui.wheel()">${icon('wheel')}随机挑一顿</button><button class="tool-tile" onclick="ui.go('orders')">${icon('order')}我的预约</button><button class="tool-tile" onclick="ui.go('feedback')">${icon('message')}给食堂留言</button></div></section><section class="side-panel profile-preview"><h3>${icon('leaf')}你的饮食偏好</h3><p>${esc(model.state.prefs.goal)} · ${model.state.prefs.tastes.map(esc).join(' / ')}<br>预算 ¥${model.state.prefs.budget}内 · ${esc(model.state.profile.recentHabit)}</p><button class="btn outline full small" onclick="ui.go('prefs')">调整我的口味档案</button></section><section class="side-panel"><div class="section-head"><h3 style="margin:0">同学最近在吃</h3><button class="link" onclick="ui.go('feed')">更多 ›</button></div>${model.state.checkins.slice(0,2).map(c=>`<button class="post-mini" style="text-align:left;width:100%" onclick="ui.detail(${c.dishId})"><span class="avatar">${esc(c.name.slice(0,1))}</span><span><strong>${esc(c.name)} · ${esc(model.dish(c.dishId).name)}</strong><p>${esc(c.text)}</p></span></button>`).join('')}</section></aside></div>`;}
function campusSvg(){const marks=venues.filter(v=>mapKind==='全部'||v.kind===mapKind).map(v=>`<g class="map-point" tabindex="0" role="button" aria-label="打开${v.name}" onclick="ui.venue(${v.id})" onkeydown="if(event.key==='Enter')ui.venue(${v.id})"><circle cx="${v.x}" cy="${v.y}" r="25" fill="${v.kind==='食堂'?'#8dbf88':v.kind==='咖啡'?'#c8a57c':'#a9b8cb'}" stroke="white" stroke-width="5"/><text x="${v.x}" y="${v.y+5}" text-anchor="middle" fill="white" font-size="13" font-weight="700">${v.kind==='食堂'?'食':v.kind==='咖啡'?'咖':'店'}</text><rect x="${v.x-52}" y="${v.y+33}" width="104" height="25" rx="7" fill="#fffffff0"/><text x="${v.x}" y="${v.y+50}" text-anchor="middle" font-size="11" fill="#8fa477">${v.name}</text></g>`).join('');return `<svg class="campus-map" viewBox="0 0 760 510" role="img" aria-label="四川农业大学成都校区美食点位示意地图"><rect width="760" height="510" rx="13" fill="#eaf1e1"/><path d="M15 480V35h705v445Z" fill="none" stroke="#d6e1c8" stroke-width="5" stroke-dasharray="8 8"/><g fill="#f8faf3"><path d="M8 280h740v30H8Z"/><path d="M245 0h27v510h-27Z"/><path d="M520 0h26v510h-26Z"/></g><g fill="#d6e0c8" stroke="#c8d5b8"><rect x="45" y="53" width="163" height="111" rx="10"/><rect x="60" y="327" width="155" height="95" rx="10"/><rect x="320" y="55" width="135" height="120" rx="10"/><rect x="306" y="211" width="144" height="67" rx="10"/><rect x="566" y="335" width="128" height="67" rx="10"/><rect x="310" y="353" width="146" height="98" rx="10"/></g><g fill="#a6ba91" font-size="12" text-anchor="middle"><text x="125" y="114">学生生活区（示意）</text><text x="387" y="436">教学区（示意）</text><text x="390" y="147">图书馆（示意）</text></g><rect x="583" y="60" width="117" height="176" rx="18" fill="#cddbb4"/><rect x="597" y="78" width="89" height="140" rx="30" fill="none" stroke="#eaf0da" stroke-width="4"/><text x="641" y="150" text-anchor="middle" fill="#9ab47d" font-size="12">运动区</text><g fill="#c0d3a6">${[[37,231],[118,232],[208,227],[321,331],[480,400],[670,449],[593,461],[47,450],[714,288],[484,50],[275,455]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="14"/>`).join('')}</g><path d="M358 510v-25h44v25" stroke="#aebf98" stroke-width="5" fill="none"/><text x="383" y="475" text-anchor="middle" fill="#9fb087" font-size="10">校区入口（示意）</text><path d="m706 438 7-21 7 21-7-5Z" fill="#9db083"/><text x="713" y="457" text-anchor="middle" fill="#9db083" font-size="10">N</text>${marks}</svg>`;}
function mapView(){if(mapLevel==='stall')return stallView();if(mapLevel==='venue')return venueView();return `${head('校园美食地图','先找到食堂，再找到档口，最后找到你想吃的那一道。')}<div class="note-bar">川农成都校区场景示意：梧桐苑、稻香苑名称参考校方资料；咖啡、超市、点位和内部平面布局均为模拟，不提供精确路径导航。</div><div class="filters">${['全部','食堂','咖啡','超市'].map(k=>`<button class="chip ${mapKind===k?'active':''}" onclick="ui.mapKind('${k}')">${k}</button>`).join('')}</div><div class="map-layout"><section class="map-card"><div class="map-toolbar"><strong>四川农业大学 · 成都校区</strong><small>点选地点查看详情</small></div><div class="map-stage">${campusSvg()}</div><div class="map-legend"><span><i class="legend-dot" style="background:#8dbf88"></i>食堂</span><span><i class="legend-dot" style="background:#c8a57c"></i>咖啡</span><span><i class="legend-dot" style="background:#a9b8cb"></i>超市</span><span>位置均为示意</span></div></section><aside class="map-side">${venues.filter(v=>mapKind==='全部'||v.kind===mapKind).map(v=>{const t=venueTraffic(v);return `<button class="venue-tile" onclick="ui.venue(${v.id})"><span class="venue-icon">${icon(v.kind==='咖啡'?'coffee':v.kind==='超市'?'cart':'shop')}</span><span><strong>${v.name}</strong><small>${v.kind} · ${t.label} · 模拟等待${t.minutes}分钟</small></span>${icon('arrow')}</button>`;}).join('')}<div class="side-panel"><h3>从校园到菜品</h3><p class="text-muted">1. 点击校园点位<br>2. 选择食堂楼层<br>3. 找到对应档口<br>4. 查看菜单、点评与预约</p><a class="link" href="https://hqfw.sicau.edu.cn/info/1019/1552.htm" target="_blank" rel="noopener">查看校方餐饮指南 ↗</a></div></aside></div>`;}
function floorSvg(v){const ss=model.state.shops.filter(s=>s.venueId===v.id&&s.floor===floor);return `<svg class="floor-plan" viewBox="0 0 700 430" role="img" aria-label="${v.name}${floor}楼档口平面示意"><rect x="25" y="25" width="650" height="365" rx="17" fill="#f7f9f1" stroke="#d6e3c7" stroke-width="3"/><rect x="70" y="160" width="560" height="93" rx="11" fill="#ecf3e2"/><text x="350" y="215" text-anchor="middle" fill="#a9bc95" font-size="17">用餐区（示意）</text><path d="M322 390v-24h57v24" fill="#d4e4bf"/><text x="351" y="358" text-anchor="middle" fill="#a9bd93" font-size="11">入口</text><rect x="42" y="299" width="62" height="57" rx="8" fill="#e6edda"/><text x="73" y="332" text-anchor="middle" fill="#a9bd93" font-size="11">楼梯</text>${ss.map((s,i)=>{const x=65+(i%4)*150,y=i<4?60:280;return `<g class="floor-point" role="button" tabindex="0" aria-label="${esc(s.name)} ${s.stall}号档口" onclick="ui.stall(${s.id})" onkeydown="if(event.key==='Enter')ui.stall(${s.id})"><rect x="${x}" y="${y}" width="120" height="72" rx="11" fill="#e3efda" stroke="#bcd6a5"/><text x="${x+60}" y="${y+27}" text-anchor="middle" font-size="11" fill="#8faf70">${s.stall}号 · ${esc(s.name)}</text><text x="${x+60}" y="${y+52}" text-anchor="middle" font-size="10" fill="#a5ba8e">${s.queue}人 · 约${s.minutes}分钟</text></g>`;}).join('')}</svg>`;}
function venueView(){const v=venue(venueId),t=venueTraffic(v),ss=model.state.shops.filter(s=>s.venueId===v.id&&s.floor===floor);return `<div class="map-breadcrumb"><button onclick="ui.mapHome()">校园美食地图</button> / ${v.name}</div><div class="venue-header"><div><h1>${v.name}</h1><p>${esc(v.description)}</p></div><span class="small-label">人流模拟 · ${t.label}</span></div><div class="filters">${v.floors.map(f=>`<button class="chip ${floor===f?'active':''}" onclick="ui.floor(${f})">${f}楼${v.id===1&&f===3?' B区（示意）':''}</button>`).join('')}</div><div class="map-layout"><section class="map-card"><div class="map-toolbar"><strong>${v.name} · ${floor}楼档口分布</strong><small>平面示意 · 点击档口看菜单</small></div>${floorSvg(v)}<p class="text-muted">档口、楼梯、入口与座位区均为交互示意，非实测建筑平面图。</p></section><aside class="map-side">${ss.map(s=>`<button class="stall-list" onclick="ui.stall(${s.id})"><span class="stall-no">${s.stall}</span><span><strong>${esc(s.name)}</strong><small>${esc(s.flavor)} · ${s.open?'营业中':'休息中'}</small></span><span class="wait ${s.minutes>5?'busy':''}">约${s.minutes}分钟</span></button>`).join('')||empty('本层菜单待补充','切换其他楼层看看。')}<div class="side-panel"><h3>${icon('message')}食堂留言</h3><p class="text-muted">想吃的菜、就餐体验和改进建议，都可以留给食堂。</p><button class="btn outline small" onclick="ui.feedbackFor(${v.id})">去留言</button></div></aside></div>`;}
function stallView(){const s=model.shop(stallId),v=venue(s.venueId),ds=model.state.dishes.filter(d=>d.shopId===s.id&&d.available);return `<div class="map-breadcrumb"><button onclick="ui.mapHome()">校园美食地图</button> / <button onclick="ui.venue(${v.id},${s.floor})">${v.name} · ${s.floor}楼</button> / ${esc(s.name)}</div>${head(esc(s.name),esc(place(s))+' · '+esc(s.hours),`<span class="small-label">${s.open?'营业中':'休息中'}</span>`)}<div class="note-bar">${esc(s.notice)}<br>${s.queue}人排队 · 预计${s.minutes}分钟（模拟） · ${s.delivery?'可预约自取 / 模拟送寝':'可预约自取'}</div><div class="section-head"><h2>档口菜单</h2><small>看点评，再决定这一顿</small></div><div class="cards">${ds.map(card).join('')||empty('菜单更新中','这个档口暂时没有在售菜品。')}</div>`;}
function feedView(){const cs=model.state.checkins.filter(c=>!myOnly||(c.owner==='self'||c.name===model.state.profile.nickname));return `${head('记录你的校园好味道','打卡一顿喜欢的，分享口味、分量和就餐体验。',`<button class="btn primary" onclick="ui.checkin()">${icon('camera')}发布打卡</button>`)}<div class="filters"><button class="chip ${!myOnly?'active':''}" onclick="ui.feedFilter(false)">同学打卡</button><button class="chip ${myOnly?'active':''}" onclick="ui.feedFilter(true)">我的打卡</button></div><div class="feed-grid">${cs.map(c=>{const d=model.dish(c.dishId);return `<article class="post-card"><div class="post-art" onclick="ui.detail(${d.id})">${c.photo?`<img src="${esc(c.photo)}" alt="打卡实拍">`:foodArt(d)}</div><div class="post-body"><div class="review-head"><span class="avatar">${esc(c.name.slice(0,1))}</span><strong>${esc(c.name)}</strong><small>${esc(c.date)}</small></div><p>${esc(c.text)}</p><div class="post-dish"><span>${esc(d.name)}</span><button class="link" onclick="ui.detail(${d.id})">查看菜品 ›</button></div></div></article>`;}).join('')||empty('还没有打卡记录','找到喜欢的美食，就来记下这一顿吧。')}</div>`;}
function mineView(){const p=model.state.profile,my=model.state.checkins.filter(c=>(c.owner==='self'||c.name===p.nickname)),rs=model.state.reviews.filter(r=>r.owner==='self'||r.name===p.nickname||r.name==='我');return `${head('我的校园美食','偏好、打卡、收藏与预约，都在这里。')}<div class="mine-banner"><span class="avatar">${esc(p.nickname.slice(0,1))}</span><div><h2>${esc(p.nickname)}</h2><p>四川农业大学 · 成都校区<br>${esc(model.state.prefs.goal)} · ${esc(p.recentHabit)}</p></div><div class="mine-stats"><span><strong>${my.length}</strong><small>我的打卡</small></span><span><strong>${rs.length}</strong><small>我的点评</small></span><span><strong>${model.state.favorites.length}</strong><small>想吃收藏</small></span></div></div><div class="mine-grid"><section class="menu-list">${[['prefs','leaf','口味与近期饮食偏好'],['myFeed','camera','我的美食打卡'],['myReviews','message','我的点评'],['favorites','heart','收藏想吃'],['orders','order','预约与送寝订单'],['feedback','message','给食堂的留言']].map(([id,ic,t])=>`<button class="menu-item" onclick="ui.go('${id}')">${icon(ic)}${t}<span>›</span></button>`).join('')}<button class="menu-item" onclick="ui.syncInfo()">${icon('settings')}保存与同步<span>查看状态 ›</span></button><button class="menu-item" onclick="ui.logout()">${icon('user')}退出体验身份<span>重新选择登录身份 ›</span></button></section><aside>${trafficPanel()}<section class="side-panel"><h3>${icon('spark')}偶尔需要一点灵感</h3><p class="panel-sub">辅助工具放在这里，需要时再打开。</p><div class="compact-tools"><button class="btn outline small" onclick="ui.assistant()">用餐推荐</button><button class="btn outline small" onclick="ui.wheel()">随机挑一顿</button></div></section><button class="help-link" onclick="ui.about()">产品说明与地图资料来源</button></aside></div>`;}
function prefsView(){const p=model.state.prefs,r=model.state.profile;return `${head('口味与近期饮食偏好','推荐会参考你的口味、预算、收藏和历史打卡。')}<div class="form-panel"><div class="form-section"><h3>近期饮食目标</h3><p>可以随时调整，不影响你浏览完整的校园菜单。</p>${['均衡饮食','减脂','增肌'].map(x=>`<button class="option ${p.goal===x?'active':''}" onclick="ui.pref('goal','${x}')">${x}</button>`).join('')}</div><div class="form-section"><h3>喜欢的口味</h3>${['家常','川味','清淡','不辣','微辣','中辣','素食','鲜香'].map(x=>`<button class="option ${p.tastes.includes(x)?'active':''}" onclick="ui.pref('tastes','${x}')">${x}${p.tastes.includes(x)?icon('check'):''}</button>`).join('')}</div><div class="form-section"><h3>近期饮食习惯</h3>${['正常三餐','最近偏清淡','常吃早餐','最近想换口味'].map(x=>`<button class="option ${r.recentHabit===x?'active':''}" onclick="ui.habit('${x}')">${x}</button>`).join('')}<div class="field"><label>补充备注（可选）</label><textarea class="input" rows="2" maxlength="200" aria-label="饮食习惯备注" placeholder="例如：近期希望少油、酱汁分开" onchange="ui.habitNote(this.value)">${esc(r.recentNote)}</textarea></div></div><div class="form-section"><h3>日常每餐预算</h3><div class="inline-row"><input type="range" style="width:70%;accent-color:#9abb7e" min="8" max="30" value="${p.budget}" aria-label="预算" oninput="ui.budget(this.value)"><span class="budget">¥<span id="budget-value">${p.budget}</span></span></div></div><div class="form-section"><h3>不想吃的食材</h3><p>根据商家填写的食材筛选；特殊饮食要求可向档口确认。</p>${['香菜','猪肉','海鲜','牛肉','鸡肉'].map(x=>`<button class="option ${p.avoid.includes(x)?'active':''}" onclick="ui.pref('avoid','${x}')">${x}${p.avoid.includes(x)?icon('check'):''}</button>`).join('')}</div><button class="btn primary" onclick="ui.go('home')">保存并看看推荐 ${icon('arrow')}</button><p class="help-text">修改即保存，首页浏览不强制隐藏预算外的菜品；用餐助手和转盘按预算与忌口筛选。</p></div>`;}
function reviewHtml(r,merchant=false){const d=model.dish(r.dishId);return `<article class="review"><div class="review-head"><span class="avatar">${esc(r.name.slice(0,1))}</span><strong>${esc(r.name)}</strong><span class="star">${'★'.repeat(r.score)}</span><small>${esc(r.date)}</small></div>${merchant?`<div class="tags"><span class="tag">${esc(d.name)}</span></div>`:''}<p>${esc(r.text)}</p><div class="tags">${r.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>${r.photo?`<img class="photo" src="${esc(r.photo)}" alt="点评实拍">`:''}${r.reply?`<div class="reply" style="margin-top:13px">商家回复：${esc(r.reply)}</div>`:''}${merchant?`<button class="btn outline small" style="margin-top:12px" onclick="ui.reply(${r.id})">${r.reply?'修改回复':'回复点评'}</button>`:''}</article>`;}
function myReviewsView(){const rs=model.state.reviews.filter(r=>r.owner==='self'||r.name===model.state.profile.nickname||r.name==='我');return head('我的点评','你分享的真实感受，都留在这里。')+rs.map(r=>reviewHtml(r)).join('')+(rs.length?'':empty('还没有发布点评','从菜品详情留下你吃过后的感受。'));}
function ordersView(merchant=false){const os=model.state.orders.filter(o=>!merchant||o.shopId===activeShop().id);return `${head(merchant?'订单处理':'我的预约订单',merchant?'接单与出餐状态会同步给学生查看。':'预约、自取与送寝进度，按订单查看。')}<div class="note-bar">${merchant?'订单履约为模拟操作，体验接单、制作、取餐或配送。':'预约与送寝为模拟流程，无真实支付或配送；商家身份可推进当前体验空间的订单。'}</div>${os.map(o=>orderCard(o,merchant)).join('')||empty('还没有预约订单',merchant?'学生预约本档口菜品后，订单将显示在这里。':'打开一道喜欢的菜品，体验预约自取或送到寝室。')}`;}
function orderCard(o,merchant=false){const d=model.dish(o.dishId),steps=['待接单','制作中',o.type==='送餐到寝'?'配送中':'待取餐','已完成'],idx=steps.indexOf(o.status);return `<article class="order-card"><div class="order-head"><span>${esc(model.shop(o.shopId).name)} · #${String(o.id).slice(-6)}</span><span class="status ${o.status==='已完成'?'done':''}">${esc(o.status)}</span></div><div class="order-body"><div class="order-art">${foodArt(d)}</div><div><h3>${esc(o.name)} × ${o.quantity}</h3><p>${esc(o.type)} · ${esc(o.time)}<br>${esc(o.address||place(model.shop(o.shopId)))}</p></div><span class="order-total">¥${o.total}</span></div>${o.note?`<p class="text-muted">备注：${esc(o.note)}</p>`:''}<div class="order-footer"><span>${esc(o.created)}${o.type==='送餐到寝'?' · 送寝费¥2':''}</span><div>${merchant&&idx>=0&&idx<3?`<button class="btn primary small" onclick="ui.advance(${o.id})">${['接单并制作',o.type==='送餐到寝'?'开始配送':'通知取餐','确认完成'][idx]}</button>`:''}${!merchant&&o.status==='待接单'?`<button class="btn outline small" onclick="ui.cancel(${o.id})">取消预约</button>`:''}${!merchant&&o.status==='已完成'?`<button class="btn soft small" onclick="ui.review(${o.dishId})">评价这一顿</button>`:''}<button class="btn outline small" onclick="ui.detail(${o.dishId})">查看菜品</button></div></div>${idx>=0?`<div class="timeline">${steps.map((s,i)=>`<span class="${i<=idx?'reached':''}">${s}</span>`).join('')}</div>`:''}</article>`;}
function feedbackView(merchant=false){const fs=model.state.feedback.filter(f=>!merchant||f.venueId===activeShop().venueId);return `${head(merchant?'食堂留言与回应':'给食堂留言',merchant?'听取同学的建议，并告知处理安排。':'想吃的菜、就餐体验和改进建议，都可以说。',merchant?'':'<button class="btn primary" onclick="ui.feedbackFor()">写一条留言</button>')}<div class="note-bar">留言为当前账号的体验记录，会显示在对应食堂的商家反馈页。</div>${fs.map(f=>`<article class="feedback-card"><h4>${venue(f.venueId).name} · ${esc(f.type)} <span class="tag">${f.reply?'已回应':'待回应'}</span></h4><p>${esc(f.text)}</p><span class="text-muted">${esc(f.date)}</span>${f.reply?`<div class="reply" style="margin-top:13px">食堂回复：${esc(f.reply)}</div>`:''}${merchant?`<button class="btn outline small" style="margin-top:12px" onclick="ui.replyFeedback(${f.id})">回复留言</button>`:''}</article>`).join('')||empty('还没有留言',merchant?'学生给对应食堂留言后，将显示在这里。':'你的一条具体建议，可以帮助食堂做得更好。')}`;}
function dashboardView(){const s=activeShop(),os=model.state.orders.filter(o=>o.shopId===s.id),pending=os.filter(o=>!['已完成','已取消'].includes(o.status)),ds=model.state.dishes.filter(d=>d.shopId===s.id),rs=model.state.reviews.filter(r=>model.dish(r.dishId).shopId===s.id&&!r.reply);return `<section class="merchant-banner"><div><h1>${esc(s.name)}，欢迎回来。</h1><p>${esc(place(s))} · ${s.open?'营业中':'休息中'} · 商家模拟身份</p></div><button class="btn primary small" onclick="ui.editDish()">${icon('plus')}发布新菜</button></section><div class="metrics"><div class="metric"><small>在售菜品</small><strong>${ds.filter(d=>d.available).length}</strong><em>可编辑与上新</em></div><div class="metric"><small>待处理订单</small><strong>${pending.length}</strong><em>预约自取与模拟送寝</em></div><div class="metric"><small>未回复点评</small><strong>${rs.length}</strong><em>听听同学的感受</em></div><div class="metric"><small>模拟排队人数</small><strong>${s.queue}</strong><em>预计等待${s.minutes}分钟</em></div></div><div class="two-col"><section><div class="section-head"><h2>待处理预约</h2><button class="link" onclick="ui.go('merchantOrders')">查看全部 ›</button></div>${pending.slice(0,3).map(o=>orderCard(o,true)).join('')||empty('暂时没有待处理预约','退出商家身份后，可以学生身份预约本档口菜品。')}<div class="section-head" style="margin-top:25px"><h2>最近点评</h2><button class="link" onclick="ui.go('merchantReviews')">查看全部 ›</button></div>${model.state.reviews.filter(r=>model.dish(r.dishId).shopId===s.id).slice(0,2).map(r=>reviewHtml(r,true)).join('')}</section><aside><div class="side-panel"><h3>${icon('clock')}营业与排队</h3><p class="panel-sub">${s.open?'当前营业':'当前休息'} · ${s.queue}人排队<br>模拟预计等待 ${s.minutes}分钟</p><button class="btn outline small" onclick="ui.go('settings')">更新人流与排队状态</button></div><div class="side-panel"><h3>${icon('truck')}配送服务</h3><p class="panel-sub">${s.delivery?'已开启模拟送餐到寝':'当前仅支持到店自取'}</p><button class="btn outline small" onclick="ui.go('settings')">维护服务开关</button></div><div class="side-panel"><h3>${icon('message')}食堂留言</h3><p class="panel-sub">${model.state.feedback.filter(f=>f.venueId===s.venueId&&!f.reply).length}条留言待回应</p><button class="btn outline small" onclick="ui.go('merchantReviews')">看看同学的建议</button></div></aside></div>`;}
function manageView(){const ds=model.state.dishes.filter(d=>d.shopId===activeShop().id);return `${head('菜品管理','维护价格、分类、口味、食材和上架状态。','<button class="btn primary" onclick="ui.editDish()">发布新菜品</button>')}<div class="table-wrap"><table><thead><tr><th>菜品</th><th>分类</th><th>价格</th><th>状态</th><th>评分</th><th>操作</th></tr></thead><tbody>${ds.map(d=>`<tr><td><strong>${esc(d.name)}</strong><small>${d.tags.map(esc).join(' · ')}</small></td><td>${esc(d.category)}</td><td>¥${d.price}</td><td><span class="tag">${d.available?'在售':'已下架'}${d.isNew?' · 新品':''}</span></td><td>${d.count?'★ '+d.rating:'待评分'}</td><td><button class="btn outline small" onclick="ui.editDish(${d.id})">编辑</button> <button class="btn soft small" onclick="ui.toggleDish(${d.id})">${d.available?'下架':'上架'}</button></td></tr>`).join('')}</tbody></table></div>`;}
function merchantReviewsView(){const rs=model.state.reviews.filter(r=>model.dish(r.dishId).shopId===activeShop().id);return head('点评与留言','回应就餐体验，也处理同学给食堂的建议。')+`<div class="section-head"><h2>菜品点评</h2></div>`+(rs.map(r=>reviewHtml(r,true)).join('')||empty('暂时没有点评','学生发布本档口菜品评价后，会显示在这里。'))+`<div style="margin-top:30px">${feedbackView(true)}</div>`;}
function settingsView(){const s=activeShop();return `${head('门店设置','营业信息、排队状态和送寝开关会同步到学生端。')}<form class="form-panel" onsubmit="ui.saveShop(event)"><div class="form-grid"><div class="field"><label>档口名称</label><input class="input" name="name" value="${esc(s.name)}" maxlength="30" required></div><div class="field"><label>楼层与档口位置</label><input class="input" value="${esc(place(s))}" readonly></div><div class="field"><label>营业时间</label><input class="input" name="hours" value="${esc(s.hours)}" maxlength="80" required></div><div class="field"><label>主要风味</label><input class="input" name="flavor" value="${esc(s.flavor)}" maxlength="60" required></div></div><div class="field"><label>门店公告 / 新品说明</label><textarea class="input" name="notice" maxlength="200" rows="3">${esc(s.notice)}</textarea></div><div class="form-grid"><div class="field"><label>模拟排队人数</label><input class="input" type="number" min="0" max="100" name="queue" value="${s.queue}" required></div><div class="field"><label>模拟预计等待分钟</label><input class="input" type="number" min="0" max="120" name="minutes" value="${s.minutes}" required></div></div><div class="check-tags"><label><input type="checkbox" name="open" ${s.open?'checked':''}>当前营业（模拟）</label><label><input type="checkbox" name="delivery" ${s.delivery?'checked':''}>提供模拟送餐到寝</label></div><button class="btn primary">保存门店设置 ${icon('check')}</button></form>`;}
const views={home:homeView,map:mapView,feed:feedView,mine:mineView,prefs:prefsView,orders:()=>ordersView(),feedback:()=>feedbackView(),myReviews:myReviewsView,myFeed:()=>{myOnly=true;return feedView();},favorites:()=>{category='全部';sort='收藏';query='';return head('收藏想吃','下次不知道吃什么，就从这里挑一顿。')+`<div class="cards">${listing()}</div>`;},dashboard:dashboardView,manage:manageView,merchantOrders:()=>ordersView(true),merchantReviews:merchantReviewsView,settings:settingsView};
function modal(html,wide=false){$('#modal-root').innerHTML=`<div class="modal-overlay" onclick="if(event.target===this)ui.close()"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="校味操作窗口"><button class="modal-close" aria-label="关闭" onclick="ui.close()">${icon('close')}</button><div class="modal-content">${html}</div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('.modal-close')?.focus(),20);}
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),2800);}
const ui={
 toast,go(p){if(!session||!views[p])return;const allowed=session.role==='merchant'?merchantNav.map(n=>n[0]):Object.keys(views).filter(x=>!merchantNav.some(n=>n[0]===x));if(!allowed.includes(p))return;page=p;if(p==='feed')myOnly=false;render();window.scrollTo({top:0,behavior:'smooth'});},close(){$('#modal-root').innerHTML='';document.body.style.overflow='';},loginRole(role){loginRole=role;render();},login(e){e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')).trim();if(!name){toast('请输入体验昵称');return;}session={role:loginRole,name,shopId:Number(f.get('shopId'))||1};if(session.role==='student'){model.state.profile.nickname=name;model.persist();}try{sessionStorage.setItem('xiaowei-session',JSON.stringify(session));}catch(e){}page=session.role==='merchant'?'dashboard':'home';render();toast(session.role==='student'?'欢迎来发现校园好味道':'已进入档口工作台');},logout(){modal('<h2>退出当前体验身份？</h2><p>回到登录页后，可以重新选择学生或商家。当前美食记录会保留。</p><div class="modal-actions"><button class="btn outline" onclick="ui.close()">继续体验</button><button class="btn primary" onclick="ui.confirmLogout()">退出体验身份</button></div>');},confirmLogout(){session=null;try{sessionStorage.removeItem('xiaowei-session');}catch(e){}this.close();render();},category(name){category=name;page='home';render();},filter(f){sort=f;page='home';render();},search(v){query=v;const list=$('#food-list');if(list)list.innerHTML=listing();},searchSubmit(e){e.preventDefault();query=new FormData(e.target).get('query').trim();$('#food-list').innerHTML=listing();},favorite(id){model.favorite(Number(id));render();toast(model.state.favorites.includes(Number(id))?'已收藏，下次想吃就能找到':'已取消收藏');},mapHome(){if(session?.role!=='student')return;mapLevel='campus';page='map';render();},mapKind(k){mapKind=k;render();},venue(id,f){venueId=Number(id);floor=Number(f)||venue(id).floors[0];mapLevel='venue';page='map';render();window.scrollTo({top:0,behavior:'smooth'});},floor(f){floor=Number(f);render();},stall(id){stallId=Number(id);const s=model.shop(id);venueId=s.venueId;floor=s.floor;mapLevel='stall';page='map';render();window.scrollTo({top:0,behavior:'smooth'});},feedFilter(v){myOnly=v;render();},pref(key,value){const p=model.state.prefs;if(key==='goal')p.goal=value;else p[key]=p[key].includes(value)?p[key].filter(x=>x!==value):[...p[key],value];model.persist();render();},habit(value){model.state.profile.recentHabit=value;model.persist();render();},habitNote(value){model.state.profile.recentNote=value.trim();model.persist();toast('饮食备注已保存');},budget(v){model.state.prefs.budget=Number(v);model.persist();$('#budget-value').textContent=v;},
 detail(id){const d=model.dish(id);if(!d)return;const s=model.shop(d.shopId),student=session?.role==='student';modal(`<div class="detail-top"><div class="detail-art">${foodArt(d)}</div><div class="detail-info"><span class="tag">${esc(d.category)}${d.isNew?' · 本周上新':''}</span><h2>${esc(d.name)}</h2><div class="place">${icon('pin')}${esc(place(s))}</div><div class="rating-row"><span class="star">★ ${d.count?d.rating:'待评分'}</span> · ${d.count}条点评</div><span class="price"><small>¥</small>${d.price}</span><div class="tags">${d.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></div></div><p>${esc(d.description)}</p><p class="text-muted">食材：${d.ingredients.map(esc).join('、')}<br>${s.open?'模拟营业中':'模拟休息中'} · ${s.queue}人排队 · 约${s.minutes}分钟 · 菜品图为插画示意</p>${student?`<div class="detail-actions"><button class="btn primary" onclick="ui.review(${d.id})">${icon('message')}写点评</button><button class="btn soft" onclick="ui.checkin(${d.id})">${icon('camera')}打卡</button><button class="btn outline" onclick="ui.reserve(${d.id})" ${!s.open||!d.available?'disabled':''}>预约点餐</button></div><div class="compact-tools"><button class="link" onclick="ui.favorite(${d.id})">${model.state.favorites.includes(d.id)?'已收藏':'收藏想吃'}</button><button class="link" onclick="ui.share(${d.id})">分享菜品</button><button class="link" onclick="ui.close();ui.stall(${s.id})">看看档口位置 ›</button></div>`:''}<h3>同学点评</h3>${model.state.reviews.filter(r=>r.dishId===d.id).map(r=>reviewHtml(r)).join('')||'<p class="text-muted">还没有具体点评，欢迎留下你的真实感受。</p>'}`,true);},
 review(id){if(session?.role!=='student')return;const d=model.dish(id);reviewScore=5;photo='';modal(`<h2>评价 ${esc(d.name)}</h2><p>具体说说口味、分量、性价比和等待体验。</p><form onsubmit="ui.submitReview(event,${d.id})"><div class="score-buttons" id="score-buttons">${[1,2,3,4,5].map(i=>`<button type="button" class="selected" aria-label="${i}分" onclick="ui.score(${i})">★</button>`).join('')}</div><div class="check-tags">${['口味好','分量足','性价比高','食材新鲜','偏咸','等得有点久'].map(t=>`<label><input type="checkbox" name="tag" value="${t}">${t}</label>`).join('')}</div><textarea class="input" name="text" aria-label="点评内容" rows="4" maxlength="300" placeholder="说说你吃过后的真实感受…" required></textarea><div class="inline-row" style="margin-top:12px"><label class="btn outline small">上传实拍<input type="file" accept="image/*" hidden onchange="ui.upload(this)"></label><span id="upload-status" class="help-text">可选，自动优化图片</span></div><div class="check-tags"><label><input type="checkbox" name="checkin">同时保存到我的美食打卡</label></div><div class="modal-actions"><button class="btn primary">发布点评</button></div></form>`);},score(v){reviewScore=v;$('#score-buttons').innerHTML=[1,2,3,4,5].map(i=>`<button type="button" class="${i<=v?'selected':''}" aria-label="${i}分" onclick="ui.score(${i})">★</button>`).join('');},submitReview(e,id){e.preventDefault();const f=new FormData(e.target);try{model.addReview(id,reviewScore,f.get('text'),f.getAll('tag'),photo);if(f.has('checkin'))model.checkin(id,f.get('text'),photo);this.detail(id);render();toast('点评已发布，商家可以回复');}catch(err){toast(err.message);}},
 checkin(id){if(session?.role!=='student')return;photo='';const ds=model.state.dishes.filter(d=>d.available);modal(`<h2>记下这一顿好味道</h2><p>打卡你吃过的美食，留下一句话或一张实拍。</p><form onsubmit="ui.submitCheckin(event)"><div class="field"><label>打卡菜品</label><select class="input" name="dishId">${ds.map(d=>`<option value="${d.id}" ${d.id===Number(id)?'selected':''}>${esc(d.name)} · ${esc(model.shop(d.shopId).name)}</option>`).join('')}</select></div><div class="field"><label>这一顿的感受</label><textarea class="input" name="text" maxlength="300" rows="4" placeholder="例如：今天试了这道新菜，喜欢它的酸甜口味。" required></textarea></div><div class="inline-row"><label class="btn outline small">添加实拍图<input type="file" accept="image/*" hidden onchange="ui.upload(this)"></label><span id="upload-status" class="help-text">可选，图片不超过8MB</span></div><div class="modal-actions"><button class="btn primary">发布美食打卡</button></div></form>`);},submitCheckin(e){e.preventDefault();const f=new FormData(e.target);try{model.checkin(Number(f.get('dishId')),f.get('text'),photo);this.close();myOnly=true;page='feed';render();toast('打卡已保存');}catch(err){toast(err.message);}},upload(input){const file=input.files?.[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>8*1024*1024){toast('请选择不超过8MB的图片');input.value='';return;}const url=URL.createObjectURL(file),img=new Image();const status=$('#upload-status');if(status)status.textContent='正在优化图片…';img.onload=()=>{const canvas=document.createElement('canvas'),scale=Math.min(1,640/Math.max(img.width,img.height));canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);let data=canvas.toDataURL('image/jpeg',.6);if(data.length>100000)data=canvas.toDataURL('image/jpeg',.35);URL.revokeObjectURL(url);if(data.length>100000){if(status)status.textContent='图片较复杂，请换一张更小的';return;}photo=data;if(status)status.textContent='已添加实拍图 · '+Math.round(data.length*.75/1024)+'KB';};img.onerror=()=>{URL.revokeObjectURL(url);if(status)status.textContent='图片读取失败，请换一张';};img.src=url;},
 reserve(id){if(session?.role!=='student')return;const d=model.dish(id),s=model.shop(d.shopId);if(!d.available||!s.open){toast('这道菜暂时不能预约');return;}modal(`<h2>预约 ${esc(d.name)}</h2><p>${esc(place(s))} · ¥${d.price}/份</p><form onsubmit="ui.submitOrder(event,${d.id})"><div class="field"><label>取餐方式</label><select name="type" class="input" onchange="ui.deliveryChange(this.value)"><option>到店自取</option>${s.delivery?'<option>送餐到寝</option>':''}</select></div><div class="form-grid"><div class="field"><label>份数</label><input class="input" name="quantity" type="number" min="1" max="10" value="1" required oninput="ui.orderTotal(${d.id})"></div><div class="field"><label>预约时段</label><select class="input" name="time"><option>今日午餐 12:15</option><option>今日午餐 12:45</option><option>今日晚餐 18:00</option><option>明日午餐 12:15</option></select></div></div><div class="field" id="address-field" hidden><label>寝室楼栋与房间</label><input class="input" name="address" placeholder="例：8号宿舍楼 302室" maxlength="60"></div><div class="field"><label>备注（可选）</label><textarea class="input" name="note" rows="2" maxlength="100" placeholder="例：少辣、不加香菜"></textarea></div><div class="modal-note">这是模拟预约，不产生真实支付或配送。送寝费用示例为每单¥2。</div><div class="modal-actions"><span class="price" id="order-total">¥${d.price}</span><button class="btn primary">确认预约</button></div></form>`);window.reservedDish=d.id;},deliveryChange(type){$('#address-field').hidden=type!=='送餐到寝';$('#address-field input').required=type==='送餐到寝';this.orderTotal(window.reservedDish);},orderTotal(id){const f=$('.modal form'),q=Number(f.querySelector('[name=quantity]').value)||1,type=f.querySelector('[name=type]').value;$('#order-total').textContent='¥'+(model.dish(id).price*q+(type==='送餐到寝'?2:0));},submitOrder(e,id){e.preventDefault();const f=new FormData(e.target);try{model.order(id,Number(f.get('quantity')),f.get('type'),f.get('time'),f.get('address')||'',f.get('note')||'');this.close();this.go('orders');toast('模拟预约成功，商家可以接单');}catch(err){toast(err.message);}},cancel(id){const o=model.state.orders.find(x=>x.id===Number(id));if(o?.status==='待接单'){o.status='已取消';model.persist();render();toast('预约已取消');}},advance(id){if(session?.role!=='merchant')return;const o=model.state.orders.find(o=>o.id===Number(id));if(!o||o.shopId!==activeShop().id)return;try{model.advance(id);render();toast('订单状态已更新');}catch(err){toast(err.message);}},
 feedbackFor(id){const selected=id||1;modal(`<h2>给食堂留言</h2><p>把具体问题和想吃的菜说清楚，方便食堂回应。</p><form onsubmit="ui.submitFeedback(event)"><div class="form-grid"><div class="field"><label>留言对象</label><select class="input" name="venueId">${venues.map(v=>`<option value="${v.id}" ${v.id===Number(selected)?'selected':''}>${v.name}</option>`).join('')}</select></div><div class="field"><label>留言类型</label><select class="input" name="type"><option>想吃的新菜</option><option>口味与分量</option><option>排队与服务</option><option>其他建议</option></select></div></div><textarea class="input" name="text" rows="4" maxlength="300" placeholder="例如：希望增加清淡的素食套餐。" required></textarea><div class="modal-actions"><button class="btn primary">提交留言</button></div></form>`);},submitFeedback(e){e.preventDefault();const f=new FormData(e.target);try{model.addFeedback(f.get('venueId'),f.get('type'),f.get('text'));this.close();page='feedback';render();toast('留言已提交，商家可以回应');}catch(err){toast(err.message);}},replyFeedback(id){const f=model.state.feedback.find(f=>f.id===Number(id));if(session?.role!=='merchant'||f.venueId!==activeShop().venueId)return;modal(`<h2>回复食堂留言</h2><p>${esc(f.text)}</p><form onsubmit="ui.saveFeedbackReply(event,${f.id})"><textarea class="input" name="reply" rows="4" maxlength="300" required>${esc(f.reply)}</textarea><div class="modal-actions"><button class="btn primary">发布回应</button></div></form>`);},saveFeedbackReply(e,id){e.preventDefault();const f=model.state.feedback.find(f=>f.id===Number(id));if(f.venueId!==activeShop().venueId)return;f.reply=new FormData(e.target).get('reply').trim();model.persist();this.close();render();toast('食堂回应已发布');},reply(id){const r=model.state.reviews.find(r=>r.id===Number(id));if(session?.role!=='merchant'||model.dish(r.dishId).shopId!==activeShop().id)return;modal(`<h2>回复这条点评</h2><p>${esc(r.text)}</p><form onsubmit="ui.saveReply(event,${r.id})"><textarea class="input" name="reply" rows="4" maxlength="300" required>${esc(r.reply)}</textarea><div class="modal-actions"><button class="btn primary">发布回复</button></div></form>`);},saveReply(e,id){e.preventDefault();const r=model.state.reviews.find(r=>r.id===Number(id));if(model.dish(r.dishId).shopId!==activeShop().id)return;r.reply=new FormData(e.target).get('reply').trim();model.persist();this.close();render();toast('回复已发布到菜品详情');},
 editDish(id){if(session?.role!=='merchant')return;const d=id?model.dish(id):{name:'',price:12,category:'食堂美食',diet:'均衡饮食',tags:['家常','微辣'],ingredients:[],art:'rice',description:'',isNew:true};if(id&&d.shopId!==activeShop().id)return;modal(`<h2>${id?'编辑菜品':'发布新菜品'}</h2><p>${esc(activeShop().name)} · ${esc(place(activeShop()))}</p><form onsubmit="ui.saveDish(event,${id||0})"><div class="field"><label>菜品名称</label><input class="input" name="name" value="${esc(d.name)}" maxlength="25" required></div><div class="form-grid"><div class="field"><label>分类</label><select class="input" name="category">${cats.map(([n])=>`<option ${d.category===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>价格（元）</label><input class="input" name="price" type="number" min="1" max="100" step="0.5" value="${d.price}" required></div><div class="field"><label>饮食目标标签</label><select class="input" name="diet">${['均衡饮食','减脂','增肌'].map(t=>`<option ${d.diet===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>示意插画</label><select class="input" name="art">${[['rice','盖饭'],['noodle','面食'],['salad','轻食'],['dumpling','饺子'],['coffee','咖啡'],['drink','饮品'],['bread','烘焙']].map(([v,t])=>`<option value="${v}" ${d.art===v?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="field"><label>口味标签（逗号分隔）</label><input class="input" name="tags" value="${esc(d.tags.join('，'))}" maxlength="100" required></div><div class="field"><label>主要食材（逗号分隔）</label><input class="input" name="ingredients" value="${esc(d.ingredients.join('，'))}" maxlength="150" required></div><div class="field"><label>菜品介绍</label><textarea class="input" rows="2" name="description" maxlength="300">${esc(d.description)}</textarea></div><div class="check-tags"><label><input type="checkbox" name="isNew" ${d.isNew?'checked':''}>标记为本周上新</label></div><div class="modal-actions"><button type="button" class="btn outline" onclick="ui.close()">取消</button><button class="btn primary">${id?'保存修改':'发布新菜品'}</button></div></form>`);},saveDish(e,id){e.preventDefault();const f=new FormData(e.target),split=v=>String(v||'').split(/[,，、]/).map(x=>x.trim()).filter(Boolean);try{if(id&&model.dish(id).shopId!==activeShop().id)return;model.saveDish({...(id?{id}:{}),shopId:activeShop().id,name:f.get('name').trim(),price:Number(f.get('price')),category:f.get('category'),diet:f.get('diet'),tags:split(f.get('tags')),ingredients:split(f.get('ingredients')),description:f.get('description').trim(),art:f.get('art'),isNew:f.has('isNew')});this.close();render();toast('菜品已保存，学生端可查看');}catch(err){toast(err.message);}},toggleDish(id){const d=model.dish(id);if(d.shopId!==activeShop().id)return;d.available=!d.available;model.persist();render();toast(d.available?'菜品已上架':'菜品已下架');},saveShop(e){e.preventDefault();const f=new FormData(e.target),s=activeShop();Object.assign(s,{name:f.get('name').trim(),hours:f.get('hours').trim(),flavor:f.get('flavor').trim(),notice:f.get('notice').trim(),queue:Number(f.get('queue')),minutes:Number(f.get('minutes')),open:f.has('open'),delivery:f.has('delivery')});model.persist();render();toast('门店与模拟排队状态已更新');},
 assistant(){if(session?.role!=='student')return;const p=model.state.prefs;modal(`<h2>今天吃什么？</h2><p>告诉用餐助手人数、预算和口味，结合你喜欢的菜品挑选。智能推荐为规则演示，不调用大模型。</p><form onsubmit="ui.assistantSubmit(event)"><div class="field"><label>说说今天的用餐想法</label><textarea class="input" name="prompt" rows="2" maxlength="200" placeholder="例如：2个人，人均15元，想吃清淡不辣的午饭"></textarea></div><div class="form-grid"><div class="field"><label>几个人用餐</label><select class="input" name="people">${[1,2,3,4,5,6].map(i=>`<option value="${i}">${i}人</option>`).join('')}</select></div><div class="field"><label>每人预算（元）</label><input class="input" name="budget" type="number" min="5" max="50" value="${p.budget}" required></div><div class="field"><label>今天的口味</label><select class="input" name="taste"><option value="">参考我的偏好</option><option>清淡</option><option>不辣</option><option>微辣</option><option>中辣</option></select></div><div class="field"><label>近期饮食偏好</label><select class="input" name="goal">${['均衡饮食','减脂','增肌'].map(t=>`<option ${p.goal===t?'selected':''}>${t}</option>`).join('')}</select></div></div><button class="btn primary full">${icon('spark')}帮我们推荐这一顿</button></form><div id="assistant-result"></div><div class="modal-note">当前喜欢：${model.state.favorites.map(id=>model.dish(id)?.name).filter(Boolean).map(esc).join('、')||'还没有收藏'}。个人忌口会继续保留，推荐不替代向档口确认特殊饮食要求。</div>`,true);},assistantSubmit(e){e.preventDefault();const f=new FormData(e.target),text=String(f.get('prompt')||''),p=model.state.prefs;let people=Number(f.get('people')),budget=Number(f.get('budget')),goal=f.get('goal'),taste=f.get('taste'),mealCategory=null;const n=text.match(/([1-6])\s*(?:个?人|位)/);if(n)people=Number(n[1]);const b=text.match(/(?:人均|每人|预算)\s*([0-9]{1,2})/);if(b)budget=Number(b[1]);const total=text.match(/总预算\s*([0-9]{1,3})/);if(total)budget=Math.floor(Number(total[1])/people);if(/不辣|不要辣/.test(text))taste='不辣';else if(/清淡/.test(text))taste='清淡';else if(/微辣/.test(text))taste='微辣';else if(/中辣/.test(text))taste='中辣';if(/减脂/.test(text))goal='减脂';if(/增肌/.test(text))goal='增肌';if(/早餐/.test(text))mealCategory='早餐';if(/咖啡/.test(text))mealCategory='咖啡';const avoid=[...p.avoid];for(const ingredient of ['香菜','猪肉','海鲜','牛肉','鸡肉'])if(new RegExp('(?:不吃|不要|不加)'+ingredient).test(text)&&!avoid.includes(ingredient))avoid.push(ingredient);const result=model.mealPlan({people,budget,tastes:taste?[taste]:p.tastes,strictTaste:taste||null,category:mealCategory,goal,avoid});const holder=$('#assistant-result');if(!result.pool.length){holder.innerHTML=empty('暂时没有完全匹配的选择','可以调整口味或预算，再试一次。');return;}const counts=new Map();result.meal.forEach(d=>counts.set(d.id,(counts.get(d.id)||0)+1));holder.innerHTML=`<section class="assistant-result"><h3>${people}人的这一顿，建议这样搭配</h3><p>${taste?esc(taste)+' · ':''}${esc(goal)} · 每人预算¥${budget}内<br>优先匹配饮食目标和口味，并参考收藏；避开忌口、闭店与已下架菜品。</p>${[...counts].map(([id,q])=>{const d=model.dish(id);return `<div class="meal-item"><span>${esc(d.name)} × ${q}<br><small>${esc(place(model.shop(d.shopId)))}</small></span><span>¥${d.price*q} <button onclick="ui.detail(${id})">查看点评 ›</button></span></div>`;}).join('')}<p><strong>菜品合计 ¥${result.total} · 人均约¥${(result.total/people).toFixed(1)}</strong><br>配餐数量为演示建议，可点开菜品自行决定。</p></section><div class="section-head"><h3 style="margin:0">其他合适的选择</h3></div><div class="cards" style="grid-template-columns:repeat(2,minmax(0,1fr))">${result.pool.slice(0,4).map(card).join('')}</div>`;},
 wheel(){if(session?.role!=='student')return;spinning=false;const pool=wheelPool();modal(`<h2>随机挑一顿</h2><p>在预算内、无忌口且营业中的候选里随机选择。</p><div class="filters">${['菜品','窗口'].map(t=>`<button class="chip ${wheelType===t?'active':''}" onclick="ui.wheelType('${t}')">随机${t}</button>`).join('')}</div><div class="wheel-wrap"><div class="pointer"></div>${wheelSvg(pool)}<div class="wheel-center">选一顿</div></div><button id="spin-button" class="btn primary full" onclick="ui.spin()" ${pool.length?'':'disabled'}>转一下</button><div id="wheel-result" class="wheel-result">${pool.length}个合适的${wheelType} · 今日预算¥${model.state.prefs.budget}内</div>`);},wheelType(t){if(spinning)return;wheelType=t;wheelAngle=0;this.wheel();},spin(){if(spinning)return;const pool=wheelPool();if(!pool.length)return;spinning=true;const i=Math.floor(Math.random()*pool.length),angle=360/pool.length,target=(360-i*angle-angle/2)%360;wheelAngle+=1800+(target-wheelAngle%360+360)%360;$('#food-wheel').style.transform=`rotate(${wheelAngle}deg)`;$('#spin-button').disabled=true;$('#spin-button').textContent='正在挑选…';setTimeout(()=>{spinning=false;if(!$('#wheel-result'))return;const d=pool[i];$('#wheel-result').innerHTML=`<strong>${esc(d.name)}</strong><br><button class="btn outline small" style="margin-top:10px" onclick="${wheelType==='菜品'?`ui.detail(${d.id})`:`ui.close();ui.stall(${d.id})`}">${wheelType==='菜品'?'看看点评':'看看窗口菜单'}</button>`;$('#spin-button').disabled=false;$('#spin-button').textContent='再转一次';},2100);},
 async share(id){const url=new URL(window.location.href);url.searchParams.set('dish',id);try{await navigator.clipboard.writeText(url.toString());toast('菜品链接已复制');}catch(e){modal(`<h2>分享菜品</h2><p>复制下面的链接。</p><input class="input" value="${esc(url.toString())}" readonly onclick="this.select()"><div class="modal-note">体验记录按账号或浏览器独立保存，其他人打开的是示例菜品。新增菜品不跨账号公开。</div>`);}},syncInfo(){const s=window.CROUS_CLOUD||{mode:'local',text:'本机体验',revision:0};modal(`<h2>我的记录与保存状态</h2><p>${esc(s.text)} · 版本${s.revision}</p><div class="modal-note">${s.mode==='cloud'?'当前账号的偏好、打卡、点评、菜单和预约支持云端保存，同一账号可继续体验。':'当前是本机体验模式，记录保存在当前浏览器。'}${s.error?'<br>'+esc(s.error):''}</div><div class="modal-actions"><button class="btn outline" onclick="ui.exportData()">导出我的记录</button>${s.mode==='cloud'?'<button class="btn outline" onclick="window.crousCloud.reload()">读取云端版本</button><button class="btn primary" onclick="window.crousCloud.retry();ui.close()">重试保存</button>':''}</div>`);},exportData(){const blob=new Blob([JSON.stringify({product:'校味',exportedAt:new Date().toISOString(),state:model.state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='xiaowei-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出体验记录');},campus(){modal(`<h2>四川农业大学 · 成都校区</h2><p>校味以川农成都校区作为校园美食导航的场景范例。</p><div class="modal-note">食堂名称参考校方资料，档口、菜品、咖啡与超市位置和人流均为模拟；地图不是实测导航图。</div><div class="modal-actions"><button class="btn outline" onclick="ui.about()">了解资料来源</button><button class="btn primary" onclick="ui.close();ui.mapHome()">看看美食地图</button></div>`);},about(){modal(`<h2>校味 · 校园美食点评推荐</h2><p>以美食浏览、点评、反馈和打卡为核心，帮助同学选择每天想吃的那一顿。</p><div class="modal-note">学生首页：普通搜索、分类与推荐菜品。<br>美食地图：校园点位 → 食堂楼层 → 档口 → 菜品。<br>个人页面：饮食偏好、打卡、收藏、留言和预约。<br>商家端：维护菜单、上新、模拟接单和送寝、回应点评与留言。</div><p class="text-muted">校方2025年指南列出梧桐苑、稻香苑；稻香苑当时暂停营业，当前状态未核实。示例营业、人流、档口平面与菜单不代表真实情况。用餐助手按输入条件和历史偏好做规则演示，尚未调用大模型。模拟角色不构成真实商家权限。</p><div class="compact-tools"><a class="btn outline small" href="https://hqfw.sicau.edu.cn/info/1019/1552.htm" target="_blank" rel="noopener">校方餐饮资料 ↗</a><a class="btn outline small" href="https://github.com/dengmingxi666-oss/crous" target="_blank" rel="noopener">项目仓库 ↗</a>${session?'<button class="btn outline small" onclick="ui.reset()">重新开始体验</button>':''}</div>`);},reset(){modal('<h2>恢复示例数据？</h2><p>这会清除当前体验空间新增的点评、打卡、留言、订单和菜单修改，恢复示例。</p><div class="modal-actions"><button class="btn outline" onclick="ui.close()">保留记录</button><button class="btn primary" onclick="ui.confirmReset()">确认恢复</button></div>');},confirmReset(){model.reset();if(session?.role==='student'){model.state.profile.nickname=session.name;model.persist();}this.close();page=session?.role==='merchant'?'dashboard':'home';category='全部';sort='推荐';query='';render();toast('已恢复示例数据');}
};
function wheelPool(){const ds=model.recommended().filter(d=>['食堂美食','面食粉面','轻食','早餐'].includes(d.category)).slice(0,8);return wheelType==='菜品'?ds:model.state.shops.filter(s=>ds.some(d=>d.shopId===s.id));}
function wheelSvg(pool){const n=pool.length||1,colors=['#e5efd5','#f4ead1','#dce9d4','#e7ead4','#f0e1c9','#dfe8cc','#eae8d1','#e2efd8'];let slices='';for(let i=0;i<n;i++){const start=-90+i*360/n,end=start+360/n,a=start*Math.PI/180,b=end*Math.PI/180,m=(a+b)/2;slices+=n===1?`<circle cx="150" cy="150" r="145" fill="${colors[0]}"/>`:`<path d="M150 150L${150+145*Math.cos(a)} ${150+145*Math.sin(a)}A145 145 0 ${360/n>180?1:0} 1 ${150+145*Math.cos(b)} ${150+145*Math.sin(b)}Z" fill="${colors[i%8]}" stroke="white" stroke-width="3"/>`;const x=150+94*Math.cos(m),y=154+94*Math.sin(m);slices+=`<text x="${x}" y="${y}" text-anchor="middle" fill="#9cb07d" font-size="10" transform="rotate(${(start+end)/2+90} ${x} ${y})">${esc(pool[i]?.name||'暂无候选')}</text>`;}return `<svg id="food-wheel" class="wheel" style="transform:rotate(${wheelAngle}deg)" viewBox="0 0 300 300">${slices}</svg>`;}
window.ui=ui;window.campusModel=model;
document.addEventListener('keydown',e=>{if(e.key==='Escape')ui.close();if(e.key==='Tab'&&$('.modal')){const els=[...$('.modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.offsetParent!==null);if(els.length&&e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus();}else if(els.length&&!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus();}}});
window.addEventListener('storage',e=>{if(e.key===(window.CAMPUS_STORAGE_KEY||window.CROUS_STORAGE_KEY)){try{const incoming=JSON.parse(e.newValue);if(incoming){model.state=incoming;model.migrate();render();}}catch(err){}}});
render();const shared=Number(new URLSearchParams(window.location.search).get('dish'));if(shared&&session&&model.dish(shared))ui.detail(shared);
